const scripts = new Map<string, { source: string; sha: string }>();

function load(file: string): { source: string; sha: string } {
  let s = scripts.get(file);
  if (s === undefined) {
    const source = readFileSync(new URL(`./lua/${file}`, import.meta.url), "utf8");
    s = { source, sha: createHash("sha1").update(source).digest("hex") };
    scripts.set(file, s);
  }
  return s;
}

// real, src/memory-store.ts
async consume<S>(algorithm: Algorithm<S>, key: string, cost: number): Promise<Decision> {
  const { state, decision } = algorithm.step(this.entries.get(key) as S | undefined, this.now(), cost);
  // Re-insert: moves the key to the most-recently-used end.
  this.entries.delete(key);
  this.entries.set(key, state);
  if (this.entries.size > this.maxKeys) {
    const oldest = this.entries.keys().next().value as string;
    this.entries.delete(oldest);
  }
  return decision;
}

// illustrative fix, NOT in ratelimit-kit (same idea as projects/20-cache)
private oldest: Iterator<string> = this.entries.keys();

private evictOne(): void {
  let r = this.oldest.next();
  if (r.done) {                         // iterator exhausted: start a fresh one (rare)
    this.oldest = this.entries.keys();
    r = this.oldest.next();
  }
  this.entries.delete(r.value as string);
}

