export interface DraftPolicy { name: string; windowSeconds?: number }

export function rateLimitDraftHeaders(d: Decision, p: DraftPolicy): Record<string, string> {
  if (!/^[A-Za-z][A-Za-z0-9_-]*$/.test(p.name)) throw new RangeError("policy name must be a token");
  if (p.windowSeconds !== undefined && (!Number.isSafeInteger(p.windowSeconds) || p.windowSeconds < 1)) {
    throw new RangeError("windowSeconds must be an integer >= 1");
  }
  const name = `"${p.name}"`;
  const w = p.windowSeconds === undefined ? "" : `;w=${p.windowSeconds}`;
  return {
    "ratelimit-policy": `${name};q=${d.limit}${w}`,
    "ratelimit": `${name};r=${d.remaining};t=${Math.ceil(d.resetMs / 1000)}`,
  };
}

