import type { Context, Next } from "koa";
import type { RateLimiter } from "../limiter.js";
import { RateLimitError, type Decision } from "../types.js";
import { keyByIp, rateLimitHeaders, STORE_UNAVAILABLE_BODY, STORE_UNAVAILABLE_RETRY_AFTER_S,
  TOO_MANY_REQUESTS_BODY, type KeyFn, type OnStoreError } from "./http.js";

export interface KoaRateLimitOptions {
  key?: KeyFn; cost?: (ctx: Context) => number; headers?: boolean; onStoreError?: OnStoreError;
}

export function rateLimit(limiter: RateLimiter, options: KoaRateLimitOptions = {}) {
  const keyFn = options.key ?? keyByIp();
  const sendHeaders = options.headers ?? true;
  const onStoreError = options.onStoreError ?? "error";
  return async function koaRateLimit(ctx: Context, next: Next): Promise<void> {
    const key = await keyFn(ctx.req);
    if (key === undefined) return next();
    const cost = options.cost?.(ctx) ?? 1;          // outside the try: a buggy cost fn is never failed open
    let decision: Decision;
    try {
      decision = await limiter.consume(key, cost);
    } catch (error) {
      if (error instanceof RateLimitError || onStoreError === "error") throw error;
      if (onStoreError === "allow") return next();
      ctx.status = 503;
      ctx.set("retry-after", String(STORE_UNAVAILABLE_RETRY_AFTER_S));
      ctx.body = STORE_UNAVAILABLE_BODY;
      return;
    }
    if (sendHeaders || !decision.allowed) ctx.set(rateLimitHeaders(decision));
    if (decision.allowed) return next();
    ctx.status = 429;
    ctx.body = TOO_MANY_REQUESTS_BODY;
  };
}

