    expect(rs.map((r) => r.status)).toEqual([200, 200, 429]);
    expect(Number(rs[2]!.headers.get("retry-after"))).toBeGreaterThanOrEqual(1);
    expect(ran).toBe(2);
  } finally {
    server.closeAllConnections();
    server.close();
  }
});

